-- PostgreSQL / Neon. Ejecutar en SQL Editor sobre una base vacía (neondb).
-- La base se crea desde Neon: no usar CREATE DATABASE, USE ni GO.
BEGIN;
CREATE TABLE "Propietarios" (
    "IdPropietario" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" VARCHAR(100) NOT NULL,
    "Dni" VARCHAR(8) NOT NULL,
    "Telefono" VARCHAR(15) NOT NULL,
    "Email" VARCHAR(100) NOT NULL,
    CONSTRAINT "UQ_Propietarios_Dni" UNIQUE ("Dni"),
    CONSTRAINT "UQ_Propietarios_Email" UNIQUE ("Email")
);
CREATE UNIQUE INDEX "UX_Propietarios_Email_Normalizado" ON "Propietarios" (lower("Email"));
CREATE TABLE "Mascotas" (
    "IdMascota" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" VARCHAR(50) NOT NULL,
    "Especie" VARCHAR(30) NOT NULL,
    "Raza" VARCHAR(50) NOT NULL,
    "Edad" INTEGER NOT NULL,
    "Peso" NUMERIC(5,2) NOT NULL,
    "IdPropietario" INTEGER NOT NULL,
    CONSTRAINT "FK_Mascotas_Propietarios" FOREIGN KEY ("IdPropietario")
        REFERENCES "Propietarios" ("IdPropietario") ON DELETE RESTRICT
);
CREATE INDEX "IX_Mascotas_IdPropietario" ON "Mascotas" ("IdPropietario");
